:host{
  --font-sans:'Pretendard',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  --fs-base:12pt;
  --fs-sm:10pt;
  --fs-xs:8pt;

  --c-ink:#333;      
  --c-body:#777;     
  --c-copy:#555;     
  --c-muted:#999;    
  --c-faint:#888;    
  --c-faintest:#aaa; 
  --c-placeholder:#a0a0a0;

  --c-border:#ededed;
  --c-border-soft:#e9e9e9;
  --c-border-panel:#e4e4e4;
  --c-hover-bg:#f7f7f7;
  --c-chip-bg:#f3f3f3;
  --c-chip-bg-hover:#e5e5e5;
  --c-surface:#fafafa;
  --c-footer-bg:#f7f7f7;

  --c-selection-bg:#e8e8e8;
  --c-selection-fg:#222;

  --shadow-float:0 10px 30px rgba(0,0,0,.12),0 2px 8px rgba(0,0,0,.06);

  --ease-out:cubic-bezier(.22,1,.36,1);   
  --ease-inout:cubic-bezier(.65,0,.35,1); 
  --ease-standard:cubic-bezier(.4,0,.2,1);
}


*{box-sizing:border-box}
:host{color-scheme:light;font-family:var(--font-sans);color:var(--c-body);background:#fff;font-synthesis:none}
.phi-app{margin:0;line-height:1.45;-webkit-font-smoothing:antialiased;background:#fff}
.phi-app,.phi-app,.phi-app *{font-family:var(--font-sans);font-size:var(--fs-base);font-weight:400}
.phi-app{-webkit-text-size-adjust:100%;text-size-adjust:100%;scrollbar-gutter:stable}
button,input,summary{font:inherit;color:inherit}
button{cursor:pointer;background:none;border:0;padding:0}
a{color:inherit;text-decoration:none}
button,a,summary{-webkit-tap-highlight-color:transparent}
button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:1px solid var(--c-body);outline-offset:5px}
::selection{background:var(--c-selection-bg);color:var(--c-selection-fg)}
[hidden]{display:none!important}


.reveal-list{list-style:none;padding:20px 0 20px 28px;margin:0}
.reveal{position:relative}
.reveal-trigger{position:relative;display:flex;align-items:center;gap:10px;min-height:40px;padding:5px 0;list-style:none;cursor:pointer;width:fit-content;max-width:100%;font-size:var(--fs-sm);transition:transform 340ms var(--ease-out),color 260ms}
.reveal-trigger::-webkit-details-marker{display:none}
.reveal-trigger:hover,
.reveal-trigger[data-hover],.reveal-trigger:focus-visible,.reveal[open]>.reveal-trigger{transform:translateX(10px);color:var(--c-ink)}
.reveal-label{position:relative;margin-left:2px}
.reveal-label::before{content:'';position:absolute;inset:-4px -8px;border-radius:10px;background:#fff;box-shadow:var(--shadow-float);opacity:0;transition:opacity 200ms;z-index:-1;pointer-events:none}
.reveal-trigger:hover .reveal-label::before,
.reveal-trigger[data-hover] .reveal-label::before,.reveal-trigger:focus-visible .reveal-label::before,.reveal[open]>.reveal-trigger .reveal-label::before{opacity:1}
.reveal-bullet{width:14px;flex:0 0 14px;position:relative;align-self:center}
.reveal-bullet::before{content:'';position:absolute;left:4px;top:50%;transform:translateY(-50%);display:block;width:5px;height:5px;background:#444;border-radius:50%;opacity:1;transition:opacity 140ms,transform 340ms}
.reveal-bullet::after{content:'→';position:absolute;left:-4px;top:50%;transform:translateY(-50%) translateX(-3px);color:var(--c-ink);opacity:0;transition:opacity 140ms,transform 140ms}
.reveal-trigger:hover .reveal-bullet::before,
.reveal-trigger[data-hover] .reveal-bullet::before,.reveal-trigger:focus-visible .reveal-bullet::before,.reveal[open]>.reveal-trigger .reveal-bullet::before{opacity:0}
.reveal-trigger:hover .reveal-bullet::after,
.reveal-trigger[data-hover] .reveal-bullet::after,.reveal-trigger:focus-visible .reveal-bullet::after,.reveal[open]>.reveal-trigger .reveal-bullet::after{opacity:1;transform:translateY(-50%)}
.reveal-content{overflow:hidden}
.reveal-copy{padding:8px 0 24px 24px;color:var(--c-copy);font-size:var(--fs-sm);line-height:1.75}
.reveal-copy p{margin:0;word-break:keep-all;overflow-wrap:anywhere}
.reveal-copy p+p{margin-top:12px}

@media(min-width:701px){
  .reveal-list .reveal[open]{display:grid;grid-template-columns:190px minmax(0,410px);column-gap:20px;align-items:start}
  .reveal-list .reveal[open]>summary{width:auto}
  .reveal-list .reveal[open] .reveal-copy{padding:2px 0 10px}
}


.accordion-trigger{display:flex;align-items:center;gap:10px;min-height:44px;cursor:pointer;list-style:none;width:fit-content;transition:transform 340ms var(--ease-out),color 260ms}
.accordion-trigger::-webkit-details-marker{display:none}
.accordion-trigger:hover,
.accordion-trigger[data-hover],.accordion-trigger:focus-visible{transform:translateX(10px);color:var(--c-ink)}
.accordion-block[open] .accordion-trigger{color:var(--c-ink)}
.accordion-content{overflow:hidden}


.search-shell{position:relative;flex:1;max-width:280px;min-width:0}
.search-field{margin:0;display:flex;align-items:center;gap:8px;width:100%;border:1px solid transparent;padding:0 10px;border-radius:2px;transition:background 140ms,border-color 140ms}
.search-field:hover,
.search-field[data-hover],.search-shell:focus-within .search-field{background:var(--c-hover-bg);border-color:var(--c-border-soft)}
.search-input{min-width:0;width:100%;border:0;background:none;padding:8px 0;outline-offset:1px;appearance:none;color:var(--c-ink)}
.search-input::placeholder{color:var(--c-body)}
.search-input::-webkit-search-cancel-button{appearance:none}
.search-shell,.search-shell *{font-size:var(--fs-xs)}
.search-options{position:absolute;z-index:20;top:calc(100% - 1px);left:0;right:0;border:1px solid var(--c-border-soft);background:var(--c-surface);color:var(--c-body);font-size:var(--fs-base)}
.search-chips{display:flex;align-items:center;flex-wrap:wrap;gap:8px;padding:7px 10px}
.search-chips button{background:var(--c-chip-bg);padding:3px 9px;min-height:32px;border-radius:2px;color:var(--c-copy)}
.search-chips button:hover,
.search-chips button[data-hover]{background:var(--c-chip-bg-hover)}
.search-chips>span{margin-right:8px;white-space:nowrap;background:#fff;padding:0 5px}


.drawer{position:fixed;inset:0 0 0 auto;margin:0;border:0;border-left:1px solid var(--c-border-panel);background:#fff;color:var(--c-copy);padding:48px 32px;width:min(420px,100%);height:100%;max-height:100%;overflow:auto;font:inherit;transform:translateX(100%);transition:transform 520ms var(--ease-inout)}
.drawer.open{transform:translateX(0)}
.drawer::backdrop{background:#00000000;backdrop-filter:blur(0px);-webkit-backdrop-filter:blur(0px);transition:background 520ms var(--ease-inout),backdrop-filter 520ms var(--ease-inout),-webkit-backdrop-filter 520ms var(--ease-inout)}
.drawer.open::backdrop{background:#00000012;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
.drawer p{margin:0 0 24px;word-break:keep-all}
.drawer-header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:36px;color:var(--c-ink)}
.drawer-header button{min-width:44px;min-height:44px}
@media(max-width:560px){.drawer{padding:32px 24px}}


.tooltip-float{position:absolute;z-index:10;background:#fff;border-radius:10px;box-shadow:var(--shadow-float);padding:10px 14px;width:max-content;max-width:220px;color:var(--c-copy);pointer-events:none}
.tooltip-float p{margin:0;word-break:keep-all;font-size:var(--fs-sm)}
.tooltip-float p+p{margin-top:6px}
.tooltip-float p.tooltip-title{margin:0 0 4px;color:var(--c-ink);font-size:var(--fs-base)}


.site-footer{margin-top:auto;padding:54px max(32px,calc(var(--app-vw) * 6 / 100));background:var(--c-footer-bg);color:var(--c-faint)}
.site-footer,.site-footer *{font-size:var(--fs-base)}
.footer-identity{display:flex;flex-direction:column;align-items:flex-start;gap:4px}
.footer-identity p{margin:0;color:var(--c-ink)}
.footer-identity .footer-copyright{color:var(--c-faint);margin-top:4px}
.footer-social{display:flex;gap:24px;flex-wrap:wrap;margin-top:4px}
.footer-social a:hover,
.footer-social a[data-hover]{color:#222;text-decoration:underline;text-underline-offset:4px}
@media(max-width:700px){.site-footer{padding:40px 24px}}


@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}








:host{
  --bg:#fff;
  --ink:#333;     
  --gray:#999;    
  --line:#ededed; 
  --fill:#f5f5f5; 
  
  --mark:#fff1a6;
  --mark-blue:#cfe4ff;
  --mark-red:#ffd4d4;
  
  --phi-cursor:url("data:image/svg+xml;base64,") 0 1;
  --phi-cursor-pointer:url("data:image/svg+xml;base64,") 0 1;
  --phi-cursor-text:url("data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxNCIgdmlld0JveD0iMCAwIDEgMTQiIGZpbGw9Im5vbmUiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+CjxsaW5lIHgxPSIwLjUiIHkxPSIwLjUiIHgyPSIwLjUwMDAwMSIgeTI9IjEyLjk5MDEiIHN0cm9rZT0iIzMzMzMzMyIgc3Ryb2tlLWxpbmVjYXA9InJvdW5kIi8+Cjwvc3ZnPgo=") 0 7;
}


:host{
  --c-ink:var(--ink);--c-copy:var(--ink);--c-selection-fg:var(--ink);
  --c-body:var(--gray);--c-muted:var(--gray);--c-faint:var(--gray);--c-faintest:var(--gray);--c-placeholder:var(--gray);
  --c-border:var(--line);--c-border-soft:var(--line);--c-border-panel:var(--line);--c-selection-bg:var(--line);--c-chip-bg-hover:var(--line);
  --c-surface:var(--fill);--c-hover-bg:var(--fill);--c-chip-bg:var(--fill);--c-footer-bg:var(--fill);
}


:host{--fs-base:10pt;--fs-sm:10pt;--fs-xs:10pt}


:host{
  --nav-gutter:32px;
  --tab-pad-x:12px;
  --tab2-indent:16px;
  --text-start:calc(var(--nav-gutter) + var(--tab-pad-x));
}


:host{--radius:20px;--radius-sm:4px}


.phi-app{word-break:keep-all;overflow-wrap:break-word}



.toolbar{position:sticky;top:0;z-index:15;background:var(--bg);display:flex;align-items:center;gap:24px;padding:16px 32px 16px var(--text-start)}
.brand-lockup{display:flex;align-items:center;gap:6px;flex:0 0 auto}
.brand-logo{height:25px;width:25px;display:block}

.brand-word-wrap{height:25px;overflow:hidden;display:block}
.brand-word{height:29.43px;width:auto;display:block;margin-top:-0.7px}

.profile-trigger{margin-left:auto;max-width:16em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap} 


.desktop-dl{position:relative;flex:0 0 auto}
.desktop-dl-btn{display:inline-flex;align-items:center;gap:4px;padding:6px var(--tab-pad-x);border-radius:var(--radius);corner-shape:squircle;background:#333;color:#fff;white-space:nowrap;transition:background 140ms,transform 140ms var(--ease-out)}
.desktop-dl-btn:hover,
.desktop-dl-btn[data-hover],.desktop-dl-btn:focus-visible{background:#1a1a1a}
.desktop-dl-btn:active{transform:scale(.98)}
.desktop-dl-btn .caret{color:#fff}
.desktop-dl-menu{position:absolute;top:calc(100% + 8px);right:0;z-index:30;width:260px;padding:6px;background:var(--bg);border-radius:var(--radius);corner-shape:squircle;box-shadow:var(--shadow-float)}
.desktop-dl-menu[hidden]{display:none}
.ddl-item{display:flex;align-items:center;gap:8px}
.ddl-meta{margin-left:auto;font-size:.78rem;color:var(--gray)}
.ddl-hint{margin:6px 10px 4px;font-size:.78rem;line-height:1.45;color:var(--gray)}


.app-body{display:flex;align-items:flex-start}


.side-nav{width:max-content;min-width:300px;max-width:380px;flex:0 0 auto;padding:32px 24px 40px var(--nav-gutter)}
.nav-group,.nav-list{display:flex;flex-direction:column;align-items:flex-start;gap:4px}

.side-nav .nav-list{padding-right:10px}
.nav-group+.nav-group{margin-top:16px}


.nav-tab{position:relative;display:block;white-space:nowrap;text-align:left;padding:6px var(--tab-pad-x);border-radius:var(--radius);corner-shape:squircle;transition:transform 340ms var(--ease-out),background 140ms,color 140ms}
.nav-tab::before{content:'→';position:absolute;right:100%;top:50%;margin-right:8px;color:var(--ink);opacity:0;transform:translate(-3px,-50%);transition:opacity 140ms,transform 140ms}
.nav-tab:hover,
.nav-tab[data-hover],.nav-tab:focus-visible,.nav-tab.active{transform:translateX(10px);background:var(--fill);color:var(--ink)}
.nav-tab:hover::before,
.nav-tab[data-hover]::before,.nav-tab:focus-visible::before,.nav-tab.active::before{opacity:1;transform:translate(0,-50%)}


.side-nav .nav-tab{width:max-content}

.tab1{font-weight:700;color:var(--ink);letter-spacing:-.16px}

.nav-tab[data-view="findings"],.nav-tab[data-view="future"],.nav-tab[data-view="assignment"]{font-size:12pt}
.tab2{color:var(--gray);margin-left:var(--tab2-indent)}

.side-nav>.nav-group>.nav-tab.tab2{margin-left:0}
.nav-code{font-weight:700}


.nav-accordion>summary{list-style:none;cursor:pointer}
.nav-accordion>summary::-webkit-details-marker{display:none}
.nav-accordion[open] .caret{transform:rotate(180deg)}
.nav-caret{display:none;margin-left:auto}

@media(max-width:860px){
  .app-body{flex-direction:column}
  .side-nav{width:100%;min-width:0;max-width:none;flex:none;padding:20px 24px}
  .nav-group,.nav-list{flex-direction:row;flex-wrap:wrap;gap:6px}
  .nav-accordion{flex-direction:column;flex-wrap:nowrap}
  .nav-accordion>summary{display:flex;align-items:center}
  .nav-caret{display:inline-block}
  .tab1{width:100%}
  .tab2{margin-left:0}
  .nav-tab:hover,
  .nav-tab[data-hover],.nav-tab:focus-visible,.nav-tab.active{transform:none}
  .nav-tab::before{display:none}
}



.shell{flex:1;min-width:0;max-width:680px;margin:0 auto;padding:40px 32px 100px}
.prototype-note{color:var(--gray);margin:0 0 32px}


.pill{display:inline-flex;align-items:center;gap:4px;padding:6px var(--tab-pad-x);border-radius:var(--radius);corner-shape:squircle;color:var(--gray);white-space:nowrap;transition:background 140ms,color 140ms}
.pill:hover,
.pill[data-hover],.pill:focus-visible,.pill[aria-pressed="true"],.pill[aria-expanded="true"]{background:var(--fill);color:var(--ink)}
.pill-start{margin-left:calc(-1 * var(--tab-pad-x))}
.pill-end{margin-right:calc(-1 * var(--tab-pad-x))}

.pill-icon{width:28px;height:28px;justify-content:center;padding:0}
.pill-icon:disabled{opacity:.35;cursor:default;background:none}
.caret{color:var(--gray);transition:transform 340ms var(--ease-out)}
.field-label{color:var(--gray)}
.field-hint{color:var(--gray);margin:10px 0 0}


.journal-head{display:flex;align-items:center;justify-content:space-between;gap:16px}
.journal-heading{margin:0;font-weight:700;color:var(--ink)}

#journal-heading{font-size:12pt;color:#000}
.date-field{position:relative;display:inline-block}
#date-field{margin:14px 0 0}


.datepicker{position:absolute;top:calc(100% + 8px);right:calc(-1 * var(--tab-pad-x));z-index:30;width:264px;padding:14px 12px 10px;background:var(--bg);border-radius:var(--radius);corner-shape:squircle;box-shadow:var(--shadow-float)}
.dp-head{display:flex;align-items:center;justify-content:space-between;padding:0 0 8px 8px}
.dp-title{font-weight:700;color:var(--ink)}
.dp-steps{display:flex;gap:2px}
.dp-week,.dp-grid{display:grid;grid-template-columns:repeat(7,1fr);justify-items:center}
.dp-week span{color:var(--gray);padding:4px 0}
.dp-day{width:32px;height:32px;margin:1px 0;border-radius:50%;color:var(--ink);font-variant-numeric:tabular-nums;transition:background 140ms,color 140ms}
.dp-day:hover,
.dp-day[data-hover],.dp-day:focus-visible{background:var(--fill);outline:0}
.dp-day[data-today]{font-weight:700}
.dp-day[aria-selected="true"]{background:var(--ink);color:var(--bg)}
.dp-day:disabled{color:var(--gray);opacity:.45;cursor:default;background:none}
.dp-foot{display:flex;justify-content:flex-end;margin-top:6px;padding-right:var(--tab-pad-x)}

.title-input{display:block;width:100%;margin:14px 0 0;padding:6px 0 6px var(--tab-pad-x);border:0;background:none;color:#000}
.title-input::placeholder{color:#000}
.title-input:focus-visible{outline:0}

.courses{margin:14px 0 0}
.course-chips{display:flex;flex-wrap:wrap;gap:2px;margin:8px 0 0}

.course-chips .pill[aria-pressed="true"]{font-weight:700}


.editor-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:20px;padding-top:10px;border-top:1px solid var(--line)}

.editor-tools{display:flex;align-items:center;flex-wrap:wrap;gap:2px}
.editor-tools b{font-weight:700}
.editor-tools i{font-style:italic;font-synthesis:style}
.tool-sep{width:1px;height:12px;background:var(--line);margin:0 6px}

.ico-quote{width:10px;height:12px;border-left:2px solid currentColor;background:linear-gradient(currentColor,currentColor) 3px 3px/7px 1px no-repeat,linear-gradient(currentColor,currentColor) 3px 8px/5px 1px no-repeat}
.ico-code{letter-spacing:-.5px}

.ico-mark,.hl-dot{display:block;width:14px;height:14px;border-radius:3px;background:var(--mark);box-shadow:inset 0 0 0 1px rgba(0,0,0,.06)}
.phi-app[data-hl="blue"] .ico-mark,.hl-dot[data-hl="blue"]{background:var(--mark-blue)}
.phi-app[data-hl="red"] .ico-mark,.hl-dot[data-hl="red"]{background:var(--mark-red)}
.hl-group{position:relative;display:inline-flex;align-items:center}
.hl-caret{width:16px;height:28px;justify-content:center;padding:0;color:var(--gray);font-size:.7rem}
.hl-caret:hover,
.hl-caret[data-hover],.hl-caret[aria-expanded="true"]{color:var(--ink)}
.hl-menu{position:absolute;top:calc(100% + 4px);left:0;z-index:20;display:flex;gap:2px;padding:4px;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);corner-shape:squircle;box-shadow:0 6px 20px rgba(0,0,0,.08)}
.hl-menu[hidden]{display:none}
.hl-swatch{display:flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:var(--radius-sm);transition:background 140ms}
.hl-swatch:hover,
.hl-swatch[data-hover],.hl-swatch:focus-visible{background:var(--fill);outline:0}
.hl-swatch[aria-checked="true"]{background:var(--fill)}
.hl-swatch[aria-checked="true"] .hl-dot{box-shadow:inset 0 0 0 1px rgba(0,0,0,.06),0 0 0 1.5px var(--bg),0 0 0 2.5px var(--ink)}


.journal{position:relative}
.course-menu{position:absolute;z-index:30;width:248px;padding:6px;background:var(--bg);border-radius:var(--radius);corner-shape:squircle;box-shadow:var(--shadow-float)}
.cm-item{display:block;width:100%;text-align:left;white-space:nowrap;padding:5px 10px;border-radius:var(--radius);corner-shape:squircle;color:var(--gray);transition:background 140ms,color 140ms}
.cm-item:hover,
.cm-item[data-hover],.cm-item:focus-visible{background:var(--fill);color:var(--ink);outline:0}
.cm-item[aria-selected="true"]{color:var(--ink)}
.cm-item .nav-code{color:var(--ink)}

.editor{position:relative;min-height:300px;padding:18px 0 28px;color:var(--ink);line-height:1.75;word-break:keep-all;overflow-wrap:anywhere}

#editor{max-height:550px;overflow-y:auto;overscroll-behavior:contain}
.editor:focus-visible{outline:0}
.editor.is-empty::before{content:attr(data-placeholder);position:absolute;top:18px;left:0;color:var(--gray);pointer-events:none}

.editor h3{position:relative;width:fit-content;margin:22px 0 6px calc(-1 * var(--tab-pad-x));padding:4px var(--tab-pad-x);border-radius:var(--radius);corner-shape:squircle;background:var(--fill);color:var(--ink)}

#editor h3,#editor .course-box,.archive-preview h3,.archive-preview .course-box{margin-left:0}
.editor>h3:first-child,.editor>.course-box:first-child{margin-top:0}

.editor h3[data-guide]::after{content:attr(data-guide);position:absolute;left:100%;top:50%;margin-left:12px;transform:translateY(-50%);white-space:nowrap;color:var(--gray);opacity:0;filter:blur(6px);pointer-events:none;transition:opacity 340ms var(--ease-out),filter 340ms var(--ease-out)}
.editor h3[data-guide]:hover::after,
.editor h3[data-guide][data-hover]::after{opacity:1;filter:blur(0)}
.editor p{margin:0}

.course-box{width:fit-content;margin:12px 0 4px calc(-1 * var(--tab-pad-x) - 1px)}
.cb-btn,.course-tag{display:inline-flex;align-items:center;gap:4px;padding:3px var(--tab-pad-x);border:1px solid var(--line);border-radius:var(--radius);corner-shape:squircle;color:var(--ink);transition:background 140ms}
.cb-btn:hover,
.cb-btn[data-hover],.cb-btn:focus-visible,.course-box.is-open .cb-btn{background:var(--fill)}
.course-box[data-course=""] .cb-btn{color:var(--gray)}

.editor b,.editor strong{font-weight:700}

.editor b *,.editor strong *,.fi-rich b *,.fi-rich strong *{font-weight:inherit}
.editor i,.editor em{font-style:italic;font-synthesis:style}
.editor blockquote{margin:6px 0;padding:0 0 0 12px;border-left:2px solid var(--gray)}
.editor code{background:var(--fill);border:1px solid var(--line);border-radius:var(--radius-sm);padding:1px 5px}
.editor mark{background:var(--mark);color:inherit;border-radius:2px;padding:0 1px;-webkit-box-decoration-break:clone;box-decoration-break:clone}
.editor mark[data-hl="blue"]{background:var(--mark-blue)}
