.view-archive{position:relative} 

.cm-confirm{margin:0;padding:5px 10px 7px;color:var(--ink);white-space:normal}
.cm-item.cm-danger{color:var(--ink);font-weight:700}
.archive-hint{margin:6px 0 16px}
.archive-hint .pill,.fi-sync-hint .pill{margin-left:6px;vertical-align:middle}
#archive-filters{margin-bottom:10px}

.archive-list{padding-left:0;align-items:stretch}

#archive-list[hidden]{display:none}
.archive-empty{color:var(--gray);padding:6px 0}
.archive-entry .accordion-content{padding:10px 0 12px} 

.archive-preview{min-height:0;padding:0 0 10px}



.findings-hint{margin:6px 0 16px}
.findings-filters{margin-bottom:10px}

.findings-list{grid-template-columns:repeat(2,minmax(0,1fr))}
.findings-list>.fi-box-empty{grid-column:1/-1}
@media(max-width:560px){.findings-list{grid-template-columns:1fr}}

.findings-list:has(.findings-stack){display:block}
.findings-stack{display:flex;align-items:flex-start;gap:16px}
.findings-col{flex:1 1 0;min-width:0;display:flex;flex-direction:column;gap:16px}
.findings-hidden{margin-top:48px}
.findings-hidden-label{margin:0 0 10px;color:var(--gray);font-size:.78rem}

.findings-hl-pop{position:fixed;z-index:60;display:flex;gap:2px;padding:4px;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);corner-shape:squircle;box-shadow:var(--shadow-float)}
.findings-hl-pop[hidden],.findings-hl-pop [hidden]{display:none}
.hl-clear{color:var(--gray);font-size:.72rem}
.hl-clear:hover,
.hl-clear[data-hover]{color:var(--ink)}

.findings-date{color:var(--gray);font-size:.78rem}

.findings-num{flex:0 0 auto;display:inline-flex;align-items:center;justify-content:center;min-width:20px;height:20px;padding:0 6px;border-radius:10px;background:var(--ink);color:var(--bg);font-size:.72rem;font-weight:600;font-variant-numeric:tabular-nums}
.findings-body{margin-top:8px;padding-bottom:0}

.findings-edit-btn{margin-left:auto;color:var(--gray);font-size:.78rem;white-space:nowrap;padding:2px 6px;border-radius:var(--radius-sm);transition:color 140ms,background 140ms}
.findings-edit-btn:hover,
.findings-edit-btn[data-hover],.findings-edit-btn:focus-visible{color:var(--ink);background:var(--fill);outline:0}
.findings-edit-btn+.fi-box-fav{margin-left:4px}
.findings-edit-btn+.findings-edit-btn{margin-left:0} 
.findings-tools{margin-top:10px;padding:6px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.findings-edit{min-height:120px;max-height:420px;overflow-y:auto;overscroll-behavior:contain;padding:10px 0 12px}
.findings-edit h3,.findings-edit .course-box{margin-left:0}
.findings-edit-foot{display:flex;justify-content:flex-end;align-items:center;gap:8px;padding-top:10px;border-top:1px solid var(--line)}



.archive-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;align-items:start}
#archive-cards[hidden]{display:none}
.archive-favs{margin-top:10px} 
.archive-favs .fi-section-label{margin:0 0 8px}

.archive-card{padding:20px 24px 16px;border:1px solid var(--line);border-radius:var(--radius);corner-shape:squircle;background:var(--bg)}
.archive-card-head{margin-bottom:4px}
.archive-card-body{padding-bottom:0}
@media(max-width:720px){.archive-cards{grid-template-columns:1fr}}


#archive-compose-slot .archive-back{margin-bottom:16px}


.drawer{transition-duration:360ms}
.drawer::backdrop{transition-duration:360ms}
.drawer.open::backdrop{backdrop-filter:blur(5px);-webkit-backdrop-filter:blur(5px)}



.drawer-account{margin:0 0 32px;padding-bottom:28px;border-bottom:1px solid var(--line)}

.drawer-account-row{display:flex;align-items:center;gap:4px 12px;flex-wrap:wrap}
.drawer-account-signed-in{display:flex;align-items:center;gap:8px;flex:1;min-width:0}
.drawer-account-signed-in[hidden]{display:none}
.drawer .drawer-account-title{margin:0;font:inherit;font-weight:700;color:var(--ink)}
.drawer .drawer-account .field-hint{margin:4px 0 14px}
.drawer .drawer-account-email{margin:0;color:var(--ink);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.drawer .drawer-account-signed-in .pill{margin-left:auto}

.drawer .drawer-nickname{margin:4px 0 10px;font-weight:700;color:var(--ink);cursor:text;word-break:break-all}
.drawer .drawer-nickname.is-empty{font-weight:400;color:var(--gray)}
.drawer .drawer-nickname-input{width:100%;font:inherit;font-weight:700;color:var(--ink);background:var(--fill);border:0;border-radius:var(--radius-sm);padding:2px 6px;margin:-2px -6px}
.auth-google-btn{min-height:32px}

.drawer .drawer-link-row{margin:0 0 8px}
.drawer-link{display:inline-flex;align-items:center;padding:6px var(--tab-pad-x);margin-left:calc(-1 * var(--tab-pad-x));border-radius:var(--radius);corner-shape:squircle;color:var(--ink);text-decoration:none;transition:background 140ms,transform 140ms var(--ease-out)}
.drawer-link:hover,
.drawer-link[data-hover],.drawer-link:focus-visible{background:var(--fill)}
.drawer-link:active{background:var(--line);transform:scale(.98)}



.site-footer{padding-left:var(--text-start);padding-right:32px;background:none}
.site-footer,.footer-identity p,.footer-identity .footer-copyright,.footer-social a{color:var(--gray)}
.footer-social a:hover,
.footer-social a[data-hover]{color:var(--ink)}
@media(max-width:700px){.site-footer{padding-left:24px;padding-right:24px}}


@media (pointer:fine){
  .phi-app,.phi-app{cursor:var(--phi-cursor),auto}
  button:not(:disabled),a,summary,label,select:not(:disabled),input[type="checkbox"]:not(:disabled),[role="button"]{cursor:var(--phi-cursor-pointer),pointer}
  input[type="text"],input[type="search"],textarea,[contenteditable="true"]{cursor:var(--phi-cursor-text),text}
  
  .resume-row summary,.fi-done summary,.nav-accordion>summary,.fi-register,.editor ul.checklist>li::before,.fi-box-add:not(.is-editing){cursor:var(--phi-cursor-pointer),pointer}
}

*,*::before,*::after{transition:none!important;animation:none!important;caret-color:transparent}
